import pandas as pd


def clean(df):
    df = df.copy()
    # Fix island label variants (misspellings of allowed values)
    df['island'] = df['island'].replace({
        'Torgerson': 'Torgersen',
        'Bisco': 'Biscoe'
    })
    return df


def answer(df):
    df = clean(df)
    # Filter to Adelie penguins only
    adelie = df[df['species'] == 'Adelie']
    # Average bill length by island
    result = {}
    for island, group in adelie.groupby('island'):
        if group['bill_length_mm'].notna().any():
            result[island] = group['bill_length_mm'].mean()
    return result
